head.script:
// 테스트 설명, 유효성 값 설정
//  - 분리 샘플(_4) : @propval false 의 세부 하위절 담당
//    (resize=false 이면 columnMove / rowNumStatusResize / groupbyZone 이 전부 무력화됨)
//  - description 은 _1 과 동일 고정, validation 은 false 세부 3건만
scwin.tData = {
    "description" : "[gridView > P > resize]<br/>마우스 Drag 에 의한 Column 의 너비(Width) 변경을 허용할지 설정합니다.",
    "validation" : [
        "false 설정 시, columnMove 속성은 항상 false 로 동작합니다.",
        "false 설정 시, rowNumStatusResize 속성은 항상 false 로 동작합니다.",
        "false 설정 시, groupbyZone=true 여도 Header Column 이 Drag 되지 않습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con 기본값 : false (본 샘플은 resize=false 무력화 검증이 핵심)
    //  - gdl_boolean 은 index0=미설정 / index1=true / index2=false → getValue 는 행인덱스라 setSelectedIndex 로 지정
    con_resize.setSelectedIndex(2);

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - con_resize(gdl_boolean) : 미설정('') / true / false. resize 는 @dynamic N 이라 con 변경은 Target 재생성으로 반영.
//    · 미설정('') : resize 속성 미설정 = 엔진 기본값(true) → columnMove/rowNumStatusResize/groupbyZone 정상 동작(대조)
//    · true       : resize="true" → columnMove/rowNumStatusResize/groupbyZone 정상 동작(대조)
//    · false      : resize="false" → columnMove/rowNumStatusResize/groupbyZone 이 전부 무력화(항상 false 동작)
//  - 그리드에 columnMove="true", rowNumStatusResize="true", groupbyZone="true" 를 모두 설정 →
//    resize=false 일 때 이 셋이 전부 무력화됨을 검증.
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // resize 옵션 (gdl_boolean → getText 로 '' / true / false 라벨 사용)
    let resize = con_resize.getText();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] resize=(현재 [' + (resize === '' ? '미설정' : resize) + ']). 그리드에 columnMove=true, rowNumStatusResize=true, groupbyZone=true 를 모두 설정. con 변경은 Target 재생성 버튼으로 반영.\n[절차] (a) Header Column 을 좌우로 Drag → 순서 이동 시도. (b) RowNum/RowStatus 경계를 Drag → 너비 변경 시도. (c) Header Column 을 상단 groupby 영역으로 Drag → groupby 적용 시도.\n[확인] [상태 확인] 버튼으로 컬럼 순서/RowNum·RowStatus 너비/groupby 적용 여부를 관찰. resize=false 면 셋 다 무력화되어 순서 불변·너비 불변·groupby 미적용. (대조: resize=true/미설정 이면 셋 다 정상 동작)"', '', 'label1');

    // GridView 와 바인딩할 DataList (4 Column, 4 Row)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "col1": "A1", "col2": "B1", "col3": "C1", "col4": "D1" },
        { "col1": "A2", "col2": "B2", "col3": "C2", "col4": "D2" },
        { "col1": "A1", "col2": "B3", "col3": "C3", "col4": "D3" },
        { "col1": "A2", "col2": "B4", "col3": "C4", "col4": "D4" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // con 값이 있으면 resize 속성 부여, 미설정이면 속성 자체 미부여(엔진 기본값 true)
    let strAttr = '';
    if (resize !== '') {
        strAttr += ' resize="' + resize + '"';
    }

    // target 그리드 : columnMove/rowNumStatusResize/groupbyZone 모두 설정 + RowNum/RowStatus 표시
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + strAttr + ' columnMove="true" rowNumStatusResize="true" groupbyZone="true" dataList="data:dlt_bind" rowNumVisible="true" rowNumHeaderValue="No." rowStatusVisible="true" rowStatusHeaderValue="St." id="" style="width:600px;height:260px;">';
    strTarget += '<w2:caption style="" id="caption1" value="resize=false 무력화 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol1" value="col1(H)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol2" value="col2(H)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol3" value="col3(H)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol4" value="col4(H)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
};



// [상태 확인] : resize=false 시 columnMove / rowNumStatusResize / groupbyZone 무력화 여부 확인
//  - columnMove         : getColumnOrder(true) 표시 순서 ID (Drag 이동 시도 후 불변이면 무력화)
//  - rowNumStatusResize : RowNum(0)/RowStatus(1) 너비 (경계 Drag 시도 후 불변이면 무력화)
//  - groupbyZone        : groupbyStatus.grouped (Header 를 groupby 영역으로 Drag 시도 후 false 면 미적용)
scwin.btn_checkState_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("=====상태 확인 (현재 resize=[" + (con_resize.getText() === '' ? '미설정' : con_resize.getText()) + "])=====");
    bottom.setReturnValue("[columnMove] 표시 순서 ID : " + JSON.stringify(target1.getColumnOrder(true)));
    bottom.setReturnValue("[rowNumStatusResize] RowNum(0) 너비 : " + target1.getColumnWidth(0) + " / RowStatus(1) 너비 : " + target1.getColumnWidth(1));
    bottom.setReturnValue("[groupbyZone] groupby 적용 여부(grouped) : " + (target1.groupbyStatus.grouped === true));
};
